def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    frames = []
    frame_cells = set()

    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = ([(r0, c) for c in range(c0, c1 + 1)] +
                  [(r1, c) for c in range(c0, c1 + 1)] +
                  [(r, c0) for r in range(r0 + 1, r1)] +
                  [(r, c1) for r in range(r0 + 1, r1)])
        if all(grid[r][c] == color for r, c in border):
            frames.append((color, r0, r1, c0, c1))
            frame_cells.update(border)

    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in frame_cells:
                counts[color] = counts.get(color, 0) + 1

    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color

        needed = sum(1 for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1)
                    if (r - r0 - 1 + c - c0 - 1) % 2 == 0)
        fill = next((k for k, v in counts.items() if v == needed), None)
        if fill is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r - r0 - 1 + c - c0 - 1) % 2 == 0:
                        out[r][c] = fill

    return out
